func ptPage(cg *port.Cells, fw *port.Cells, fl *port.Cells, fv *port.Cells, fa *port.Cells, fx *port.Cells, hl *port.Cells, sl *port.Cells, etext *port.Cells, refs *port.Cells, words *port.Cells, lines *port.Cells, page int32) int32 {
	// One page of the hand-built layer: etext 'abcd', two words, a line, a group, verdicts, a set-aside item, an explanation,
	// a health row and a seal candidate; the page's own `etext` and `refs`.
	var g int32 = 0
	var r int32 = 0
	var ra int32 = 0
	var rh int32 = 0
	var rs int32 = 0
	port.CellsDrop(words, 0)
	port.CellsDrop(lines, 0)
	port.CellsPush(etext, 97)
	port.CellsPush(etext, 98)
	port.CellsPush(etext, 99)
	port.CellsPush(etext, 100)
	evidence.WdNew(words, page, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, 0, 2, -1, -1, -1)
	evidence.WdNew(words, page, 1000, 0, 2000, 1000, 1000, 900, 2000, 900, 0, 0, 2, 2, -1, -1, -1)
	evidence.LnNew(lines, page, 0, 0, 2000, 1000, 0, 900, 2000, 900, 0, 0, 0, 2)
	r = player.FlCopyLine(fl, lines, 0, player.FwCount(fw), 2)
	player.FwCopyWord(fw, words, 0, r)
	player.FwCopyWord(fw, words, 1, r)
	// the group: one text candidate in the evidence's words, one OCR candidate that is the layer's own first word
	g = player.CgNew(cg, page, 0, 0, 2000, 1000, 0)
	evidence.RfAdd(refs, evidence.EaWords(), 0)
	evidence.RfAdd(refs, player.PlEaFw(), player.FwCount(fw)-2)
	player.CgSet(cg, g, player.CgfTfirst(), (port.CellsLen(refs)/2)-2)
	player.CgSet(cg, g, 7, 1)
	player.CgSet(cg, g, player.CgfOfirst(), (port.CellsLen(refs)/2)-1)
	player.CgSet(cg, g, 9, 1)
	player.FvNew(fv, g, 1, 100, 900, 0)
	player.FvNew(fv, g, 1, 100, 900, 0)
	ra = player.FaNew(fa, page, 10, 10, 20, 20, model.DrInvisible(), evidence.EaWords(), 5)
	player.FaSet(fa, ra, 9, g)
	player.FxNew(fx, g, 100, 24, 950)
	rh = player.HlNew(hl, player.PlhFontPage(), page, 0)
	player.HlSet(hl, rh, 3, 1000)
	rs = player.SlNew(sl, page, 0, 0, 500, 500, player.PlsSeal())
	port.CellsSet(sl, (rs*16)+10, (port.CellsLen(refs)/2)-2)
	port.CellsSet(sl, (rs*16)+11, 2)
	return 0
}

