	port.AssertEq(emonT, player.PlCheck(pcg, pfw, pfl, pfv, pfa, pfx, phl, pfpa, psl, pet, prf, gl), 0, "a page's layer is sound")
	player.PlAppend(cg, fw, fl, fv, fa, fx, hl, fpa, sl, et, rf, pcg, pfw, pfl, pfv, pfa, pfx, phl, pfpa, psl, pet, prf)
	port.CellsDrop(pcg, 0)
	port.CellsDrop(pfw, 0)
	port.CellsDrop(pfl, 0)
	port.CellsDrop(pfv, 0)
	port.CellsDrop(pfa, 0)
	port.CellsDrop(pfx, 0)
	port.CellsDrop(phl, 0)
	port.CellsDrop(psl, 0)
	port.CellsDrop(pet, 0)
	port.CellsDrop(prf, 0)
	ptPage(pcg, pfw, pfl, pfv, pfa, pfx, phl, psl, pet, prf, words, lines, 2)
	player.PlAppend(cg, fw, fl, fv, fa, fx, hl, fpa, sl, et, rf, pcg, pfw, pfl, pfv, pfa, pfx, phl, pfpa, psl, pet, prf)
