func ptWidth(kind int32, arg int32) int32 {
	// How many cells a field of the dump table covers.
	if kind == 3 {
		return 4
	}
	if (kind == 4) || (kind == 5) {
		return 2
	}
	if kind == 7 {
		return arg
	}
	return 1
}

func TestEveryCellIsPrintedOrNamedSpare(emonT *testing.T) {
	// per arena of the field table: the cells its rows cover, plus its spare cells, are its stride, and no two rows overlap
	var a int32 = 0
	var k int32 = 0
	var covered int32 = 0
	var next int32 = 0
	var f int32 = 0
	for a < 6 {
		covered = 0
		next = 0
		k = 0
		for k < player.PlFx[a*4+1] {
			f = player.PlFd[(player.PlFx[a*4+0]+k)*6+1]
			port.AssertThat(emonT, f >= next, "the fields are in stride order and do not overlap")
			covered += ptWidth(player.PlFd[(player.PlFx[a*4+0]+k)*6+2], player.PlFd[(player.PlFx[a*4+0]+k)*6+5])
			next = f + ptWidth(player.PlFd[(player.PlFx[a*4+0]+k)*6+2], player.PlFd[(player.PlFx[a*4+0]+k)*6+5])
			k += 1
		}
		port.AssertEq(emonT, covered+player.PlFx[a*4+3], player.PlFx[a*4+2], "printed plus spare is the stride")
		a += 1
	}
	port.AssertEq(emonT, a, 6, "six arenas")
}

